    $receiptTimeZone = data_get($receipt->snapshot, 'time_zone', $receiptTimeZone ?? 'UTC');
    $receiptLocale = data_get($receipt->snapshot, 'locale', $receiptLocale ?? 'en');
    $snapshot = $receipt->snapshot;
    $currency = data_get($snapshot, 'sale.currency_code', 'INR');
    $formatter = new NumberFormatter($receiptLocale ?? 'en', NumberFormatter::CURRENCY);
    $formatter->setTextAttribute(NumberFormatter::CURRENCY_CODE, $currency);
    $digits = $formatter->getAttribute(NumberFormatter::MAX_FRACTION_DIGITS);
    $format = fn ($minor) => $currency.' '.number_format(($minor ?? 0) / (10 ** $digits), $digits);
    $methodNames = ['cash' => 'Cash', 'card' => 'Card', 'upi' => 'UPI', 'bank_transfer' => 'Bank transfer', 'payment_link' => 'Payment link', 'custom' => 'Other'];
